inline ::flatbuffers::Offset<ACIProvenance> CreateACIProvenance(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    rflMethod METHOD = rflMethod_UNSPECIFIED,
    ::flatbuffers::Offset<::flatbuffers::String> SOURCE = 0,
    ::flatbuffers::Offset<::flatbuffers::String> SOURCE_QUERY = 0,
    ::flatbuffers::Offset<::flatbuffers::String> PROPAGATOR_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> PROPAGATOR_VERSION = 0,
    ::flatbuffers::Offset<::flatbuffers::String> PROPAGATOR_CONFIGURATION = 0,
    ::flatbuffers::Offset<::flatbuffers::String> MODULE_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> MODULE_VERSION = 0,
    ::flatbuffers::Offset<::flatbuffers::String> MODULE_CONTENT_HASH = 0,
    double SAMPLING_STEP_S = 0.0,
    ::flatbuffers::Offset<::flatbuffers::String> BOUNDARY_REFINEMENT = 0,
    double BOUNDARY_TOLERANCE_S = 0.0,
    double MIN_ELEVATION_DEG = 0.0,
    uint64_t COMPUTED_AT = 0,
    uint64_t RETRIEVED_AT = 0,
    ::flatbuffers::Offset<::flatbuffers::String> LICENSE = 0,
    bool NON_COMMERCIAL_ONLY = false,
    ::flatbuffers::Offset<::flatbuffers::String> CITATION = 0) {
  ACIProvenanceBuilder builder_(_fbb);
  builder_.add_RETRIEVED_AT(RETRIEVED_AT);
  builder_.add_COMPUTED_AT(COMPUTED_AT);
  builder_.add_MIN_ELEVATION_DEG(MIN_ELEVATION_DEG);
  builder_.add_BOUNDARY_TOLERANCE_S(BOUNDARY_TOLERANCE_S);
  builder_.add_SAMPLING_STEP_S(SAMPLING_STEP_S);
  builder_.add_CITATION(CITATION);
  builder_.add_LICENSE(LICENSE);
  builder_.add_BOUNDARY_REFINEMENT(BOUNDARY_REFINEMENT);
  builder_.add_MODULE_CONTENT_HASH(MODULE_CONTENT_HASH);
  builder_.add_MODULE_VERSION(MODULE_VERSION);
  builder_.add_MODULE_ID(MODULE_ID);
  builder_.add_PROPAGATOR_CONFIGURATION(PROPAGATOR_CONFIGURATION);
  builder_.add_PROPAGATOR_VERSION(PROPAGATOR_VERSION);
  builder_.add_PROPAGATOR_ID(PROPAGATOR_ID);
  builder_.add_SOURCE_QUERY(SOURCE_QUERY);
  builder_.add_SOURCE(SOURCE);
  builder_.add_NON_COMMERCIAL_ONLY(NON_COMMERCIAL_ONLY);
  builder_.add_METHOD(METHOD);
  return builder_.Finish();
}

